def apply(inputs, premises):
    names = inputs["asset_descriptions"]
    categories = inputs["asset_categories"]
    values = inputs["asset_values"]
    citations = premises["rule_citations"]
    rule_categories = premises["rule_categories"]
    caps = premises["rule_caps"]
    claims = {}
    for i in range(len(names)):
        asset_claims = []
        for j in range(len(citations)):
            if rule_categories[j] == categories[i] or rule_categories[j] == "any":
                claim_value = min(values[i], caps[j])
                asset_claims = asset_claims + [{"citation": citations[j], "claim_value": claim_value}]
        claims[names[i]] = asset_claims
    return {"asset_descriptions": names, "claims": claims}

def apply(inputs, premises):
    names = inputs["asset_descriptions"]
    claims = inputs["claims"]
    answer = {}
    for i in range(len(names)):
        rows = claims[names[i]]
        citations = []
        for j in range(len(rows)):
            citations = citations + [rows[j]["citation"]]
        answer[names[i]] = citations
    return {"answer": answer}

def apply(inputs, premises):
    names = inputs["asset_descriptions"]
    claims = inputs["claims"]
    answer = {}
    for i in range(len(names)):
        answer[names[i]] = claims[names[i]]
    return {"answer": answer}

def apply(inputs, premises):
    year = int(inputs["tax_year"])
    amount = float(premises["general_exemption_amount"])
    if year >= int(premises["special_zero_start_year"]) and year <= int(premises["special_zero_end_year"]):
        amount = 0
    if bool(inputs["deduction_allowable_to_another_taxpayer"]):
        amount = float(premises["dependent_disallowed_amount"])
    answer = "Contradiction"
    if amount == float(inputs["proposition_exemption_amount"]):
        answer = "Entailment"
    return {"answer": answer}

def apply(inputs, premises):
    included = True
    if not bool(inputs["payment_is_cash"]):
        included = bool(premises["general_non_cash_remuneration_included"])
    if bool(inputs["is_agricultural_labor"]) and not bool(inputs["payment_is_cash"]) and bool(premises["non_cash_agricultural_remuneration_excluded"]):
        included = False
    answer = "Contradiction"
    if included == bool(inputs["proposition_says_included_as_wages"]):
        answer = "Entailment"
    return {"answer": answer}
